assembly_recipes.script:
Add-Type -AssemblyName System.Drawing
$ErrorActionPreference='Stop'
$root='<worktree>'
$out=Join-Path $root 'out/handoff/dev-shamans-relief-pair'
function EllipseWeight([double]$x,[double]$y,[double]$cx,[double]$cy,[double]$rx,[double]$ry) {
  $r=[Math]::Sqrt([Math]::Pow(($x-$cx)/$rx,2)+[Math]::Pow(($y-$cy)/$ry,2))
  return [Math]::Max(0,[Math]::Min(1,(1-$r)/0.38))
}
$items=@(
  @{id='mudang_f';label='여자 무당';y=157;eyes=111;cheek=136;mouth=156;noseTop=122;noseBottom=145;raw='<worktree>/out/handoff/dev-female-relief-review/dev-female-relief-generated.png'},
  @{id='mudang_m';label='남자 무당';y=78;eyes=102;cheek=128;mouth=148;noseTop=114;noseBottom=139;raw='<generated-raw-folder>/exec-38f1a125-1f13-46f9-b58a-640fe14cb1ee.png'}
)
$report=@()
foreach($item in $items) {
  $base=[Drawing.Bitmap]::new("$root/content/images/sprite/$($item.id).png")
  $raw=[Drawing.Bitmap]::new($item.raw)
  $norm=[Drawing.Bitmap]::new(220,275)
  $g=[Drawing.Graphics]::FromImage($norm)
  $g.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
  $g.DrawImage($raw,[Drawing.Rectangle]::new(0,0,220,275),[Drawing.Rectangle]::new(0,0,$raw.Width,$raw.Height),[Drawing.GraphicsUnit]::Pixel)
  $g.Dispose();$raw.Dispose()
  $result=$base.Clone([Drawing.Rectangle]::new(0,0,512,1280),[Drawing.Imaging.PixelFormat]::Format32bppArgb)
  $changed=0
  for($y=0;$y -lt 275;$y++) {for($x=0;$x -lt 220;$x++) {
    $w=0.0
    foreach($cx in @(83,134)) {
      $w=[Math]::Max($w,(EllipseWeight $x $y $cx $item.eyes 25 16))
      $w=[Math]::Max($w,(EllipseWeight $x $y $cx $item.cheek 22 20))
    }
    $w=[Math]::Max($w,(EllipseWeight $x $y 110 $item.mouth 31 16))
    # Entire nose remains source-exact; blend outside its protected rectangle.
    $dx=[Math]::Max(0,[Math]::Max(97-$x,$x-123))
    $dy=[Math]::Max(0,[Math]::Max($item.noseTop-$y,$y-$item.noseBottom))
    $w *= [Math]::Min(1,[Math]::Sqrt($dx*$dx+$dy*$dy)/5.0)
    if($w -le 0){continue}
    $original=$base.GetPixel($x+146,$y+$item.y);$edited=$norm.GetPixel($x,$y)
    $r=[int][Math]::Round($original.R*(1-$w)+$edited.R*$w)
    $gg=[int][Math]::Round($original.G*(1-$w)+$edited.G*$w)
    $b=[int][Math]::Round($original.B*(1-$w)+$edited.B*$w)
    $color=[Drawing.Color]::FromArgb($original.A,$r,$gg,$b)
    $result.SetPixel($x+146,$y+$item.y,$color)
    if($color.ToArgb() -ne $original.ToArgb()){$changed++}
  }}
  $result.Save("$out/$($item.id)-relief-preview.png",[Drawing.Imaging.ImageFormat]::Png)
  $comparison=[Drawing.Bitmap]::new(1040,560)
  $g=[Drawing.Graphics]::FromImage($comparison);$g.Clear([Drawing.Color]::FromArgb(248,240,230))
  $font=[Drawing.Font]::new('Malgun Gothic',17)
  $small=[Drawing.Font]::new('Malgun Gothic',10)
  $g.DrawString("$($item.label) · 현재 dev 원본",$font,[Drawing.Brushes]::Black,10,10)
  $g.DrawString('안도하는 미소 · 검토 시안',$font,[Drawing.Brushes]::Black,530,10)
  $g.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
  $src=[Drawing.Rectangle]::new(170,$item.y+62,168,155)
  $g.DrawImage($base,[Drawing.Rectangle]::new(10,55,504,465),$src,[Drawing.GraphicsUnit]::Pixel)
  $g.DrawImage($result,[Drawing.Rectangle]::new(530,55,504,465),$src,[Drawing.GraphicsUnit]::Pixel)
  $g.DrawString('원본 해상도에서 표정 영역만 반영 · 같은 배율 확대 · 게임 미반영',$small,[Drawing.Brushes]::Black,10,531)
  $comparison.Save("$out/$($item.id)-comparison.png",[Drawing.Imaging.ImageFormat]::Png)
  $g.Dispose();$font.Dispose();$small.Dispose();$comparison.Dispose()
  $noseChanges=0;$alphaChanges=0;$outsideChanges=0
  for($y=0;$y -lt 1280;$y++){for($x=0;$x -lt 512;$x++){
    $a=$base.GetPixel($x,$y);$b=$result.GetPixel($x,$y)
    if($a.A -ne $b.A){$alphaChanges++}
    if($a.ToArgb() -ne $b.ToArgb()){
      if($x -ge 243 -and $x -le 269 -and $y -ge ($item.y+$item.noseTop) -and $y -le ($item.y+$item.noseBottom)){$noseChanges++}
      if($x -lt 204 -or $x -gt 305 -or $y -lt ($item.y+$item.eyes-16) -or $y -gt ($item.y+$item.mouth+16)){$outsideChanges++}
    }
  }}
  $report += [PSCustomObject]@{id=$item.id;changedPixels=$changed;protectedNoseChanges=$noseChanges;outsideExpressionBoundsChanges=$outsideChanges;alphaChanges=$alphaChanges;size='512x1280';gameIntegrated=$false}
  $norm.Dispose();$base.Dispose();$result.Dispose()
}
$report | ConvertTo-Json | Set-Content -LiteralPath "$out/pixel-check.json" -Encoding utf8
$report | Format-Table

