using System;
public static class ResidentBlend {
 static double Ellipse(double x,double y,double cx,double cy,double rx,double ry) {
  double r=Math.Sqrt(Math.Pow((x-cx)/rx,2)+Math.Pow((y-cy)/ry,2));
  return Math.Max(0,Math.Min(1,(1-r)/.38));
 }
 public static byte[] Blend(byte[] original,byte[] generated,int top,int eye,int mouth) {
  byte[] result=(byte[])original.Clone();
  for(int y=0;y<275;y++)for(int x=0;x<220;x++) {
   double w=0;
   foreach(int cx in new int[]{84,134}) {
    w=Math.Max(w,Ellipse(x,y,cx,eye-5,27,24));
    w=Math.Max(w,Ellipse(x,y,cx,eye+27,24,24));
   }
   w=Math.Max(w,Ellipse(x,y,110,mouth,34,17));
   double dx=Math.Max(0,Math.Max(96-x,x-125));
   double dy=Math.Max(0,Math.Max(eye+12-y,y-(mouth-15)));
