$out="$root/out/handoff/dev-residents-flustered-original-v2"
$generated='<generated-raw-folder>'
$items=@(
 @{id='hunjang';label='훈장';emotion='체면을 지키며 설명하려는 순간';y=78;eye=107;mouth=159;raw='exec-7d361d68-6fa6-4a4c-8501-5b38fcb9c577.png'},
 @{id='jumo';label='주모';emotion='의심이 자신에게 돌아와 말문이 막힌 순간';y=157;eye=122;mouth=167;raw='exec-2d2fed18-77a8-4bf0-8b8c-599c6a5a5116.png'},
 @{id='blacksmith';label='대장장이';emotion='반박하려다 한 박자 멈추는 순간';y=32;eye=124;mouth=172;raw='exec-9e80637e-4a28-4f79-ba17-d016c7b70939.png'},
 @{id='meosum';label='머슴';emotion='해명하려다 말이 꼬이는 순간';y=78;eye=111;mouth=160;raw='exec-337d107b-5a24-4fb4-bd6b-ea28687a9372.png'},
 @{id='yakcho';label='약초꾼';emotion='기억을 짚으며 답을 멈추는 순간';y=78;eye=112;mouth=164;raw='exec-73b59a4e-5244-4ea2-bf0e-e49c40701938.png'},
 @{id='gwabu';label='과부';emotion='예상 밖의 지적에 말을 고르는 순간';y=157;eye=120;mouth=167;raw='exec-7297901f-b93b-4dd1-9fe5-7fe45ad57caf.png'}
)
function Read-Pixels($bitmap){
 $data=$bitmap.LockBits([Drawing.Rectangle]::new(0,0,$bitmap.Width,$bitmap.Height),[Drawing.Imaging.ImageLockMode]::ReadOnly,[Drawing.Imaging.PixelFormat]::Format32bppArgb)
 $buffer=[byte[]]::new($data.Stride*$data.Height)
 [Runtime.InteropServices.Marshal]::Copy($data.Scan0,$buffer,0,$buffer.Length)
 $bitmap.UnlockBits($data)
 return ,$buffer
}
$checks=@()
$sheet=[Drawing.Bitmap]::new(1440,1164)
$sheetCanvas=[Drawing.Graphics]::FromImage($sheet)
$sheetCanvas.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
$index=0
foreach($item in $items){
 $sourcePath="$root/content/images/sprite/$($item.id).png"
 $base=[Drawing.Bitmap]::new($sourcePath)
 Copy-Item -LiteralPath "$generated/$($item.raw)" -Destination "$out/$($item.id)-generated.png"
 $raw=[Drawing.Bitmap]::new("$out/$($item.id)-generated.png")
 $norm=[Drawing.Bitmap]::new(220,275)
 $g=[Drawing.Graphics]::FromImage($norm)
 $g.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
 $g.DrawImage($raw,[Drawing.Rectangle]::new(0,0,220,275),[Drawing.Rectangle]::new(0,0,$raw.Width,$raw.Height),[Drawing.GraphicsUnit]::Pixel)
 $g.Dispose();$raw.Dispose()
 $original=Read-Pixels $base;$generatedPixels=Read-Pixels $norm
 $resultPixels=[ResidentBlend]::Blend($original,$generatedPixels,$item.y,$item.eye,$item.mouth)
 $result=[Drawing.Bitmap]::new(512,1280,[Drawing.Imaging.PixelFormat]::Format32bppArgb)
 $data=$result.LockBits([Drawing.Rectangle]::new(0,0,512,1280),[Drawing.Imaging.ImageLockMode]::WriteOnly,[Drawing.Imaging.PixelFormat]::Format32bppArgb)
 [Runtime.InteropServices.Marshal]::Copy($resultPixels,0,$data.Scan0,$resultPixels.Length)
 $result.UnlockBits($data)
 $result.Save("$out/$($item.id)-flustered-preview.png",[Drawing.Imaging.ImageFormat]::Png)
 $comparison=[Drawing.Bitmap]::new(1040,560)
 $g=[Drawing.Graphics]::FromImage($comparison);$g.Clear([Drawing.Color]::FromArgb(248,240,230))
 $font=[Drawing.Font]::new('Malgun Gothic',17);$small=[Drawing.Font]::new('Malgun Gothic',11)
 $g.DrawString("$($item.label) · dev 원본",$font,[Drawing.Brushes]::Black,10,10)
 $g.DrawString('당황 · 원본 기준 재보완',$font,[Drawing.Brushes]::Black,530,10)
 $g.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
 $src=[Drawing.Rectangle]::new(170,$item.y+62,168,155)
 $g.DrawImage($base,[Drawing.Rectangle]::new(10,55,504,465),$src,[Drawing.GraphicsUnit]::Pixel)
 $g.DrawImage($result,[Drawing.Rectangle]::new(530,55,504,465),$src,[Drawing.GraphicsUnit]::Pixel)
 $g.DrawString("$($item.emotion) · 게임 미반영",$small,[Drawing.Brushes]::Black,10,531)
 $comparison.Save("$out/$($item.id)-comparison.png",[Drawing.Imaging.ImageFormat]::Png)
 $sheetCanvas.DrawImage($comparison,[Drawing.Rectangle]::new(($index%2)*720,[Math]::Floor($index/2)*388,720,388))
 $counts=[ResidentBlend]::Check($original,$resultPixels,$item.y,$item.eye,$item.mouth)
 $checks += [PSCustomObject]@{id=$item.id;emotion=$item.emotion;sourceSHA256=(Get-FileHash -LiteralPath $sourcePath -Algorithm SHA256).Hash;changedPixels=$counts[0];outsideExpressionBoundsChanges=$counts[1];protectedNoseChanges=$counts[2];alphaChanges=$counts[3];gameIntegrated=$false}
 $index++;$g.Dispose();$font.Dispose();$small.Dispose();$comparison.Dispose();$base.Dispose();$norm.Dispose();$result.Dispose()
}
$sheet.Save("$out/all-six-comparisons.png",[Drawing.Imaging.ImageFormat]::Png)
$sheetCanvas.Dispose();$sheet.Dispose()
$checks | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath "$out/pixel-check.json" -Encoding utf8
$checks | Select-Object id,changedPixels,outsideExpressionBoundsChanges,protectedNoseChanges,alphaChanges | Format-Table

Add-Type -AssemblyName System.Drawing
$ErrorActionPreference='Stop'
Add-Type -TypeDefinition @'
using System;
public static class ResidentBlend {
 static double Ellipse(double x,double y,double cx,double cy,double rx,double ry) {
  double r=Math.Sqrt(Math.Pow((x-cx)/rx,2)+Math.Pow((y-cy)/ry,2));
  return Math.Max(0,Math.Min(1,(1-r)/.38));
 }
 public static byte[] Blend(byte[] original,byte[] generated,int top,int eye,int mouth) {
  byte[] result=(byte[])original.Clone();
  int ox=0,oy=0; double best=double.MaxValue;
  for(int dy=-12;dy<=12;dy++)for(int dx=-8;dx<=8;dx++){
   double error=0;
   for(int y=eye+13;y<=mouth-15;y++)for(int x=98;x<=122;x++){
    int a=((y+top)*512+x+146)*4,b=((y+dy)*220+x+dx)*4;
    for(int c=0;c<3;c++){double d=original[a+c]-generated[b+c];error+=d*d;}
   }
   if(error<best){best=error;ox=dx;oy=dy;}
  }
  double targetEyeY=0,rawEyeY=0;
  foreach(int cx in new int[]{84,134}){
   double aw=0,ay=0,bw=0,by=0;
   for(int y=eye-12;y<=eye+12;y++)for(int x=cx-7;x<=cx+7;x++){
    int a=((y+top)*512+x+146)*4,b=((y+oy)*220+x+ox)*4;
    double va=Math.Max(0,110-(original[a]+original[a+1]+original[a+2])/3.0);
    double vb=Math.Max(0,110-(generated[b]+generated[b+1]+generated[b+2])/3.0);
    if(y>=eye-7&&y<=eye+7){aw+=va;ay+=va*y;}bw+=vb;by+=vb*y;
   }
   targetEyeY+=aw>0?ay/aw:eye;rawEyeY+=bw>0?by/bw:eye;
  }
  int eyeShift=oy+(int)Math.Round((rawEyeY-targetEyeY)/2.0);
  double mw=0,my=0;
  for(int y=mouth-12;y<=mouth+12;y++)for(int x=100;x<=120;x++){
   int b=((y+oy)*220+x+ox)*4;
   double v=Math.Max(0,125-(generated[b]+generated[b+1]+generated[b+2])/3.0);mw+=v;my+=v*y;
  }
  int mouthShift=oy+(int)Math.Round((mw>0?my/mw:mouth)-mouth);
  System.Console.WriteLine("feature shifts: eyes="+eyeShift+", mouth="+mouthShift+", nose="+oy);
  for(int y=0;y<275;y++)for(int x=0;x<220;x++){
   if(x+ox<0||x+ox>=220||y+oy<0||y+oy>=275)continue;
   double w=0;
   foreach(int cx in new int[]{84,134}){
    // Brows are restored from original pixels below; no regenerated brow texture.
    double upper=Ellipse(x,y,cx,eye-1,22,12);
    upper*=Math.Max(0,Math.Min(1,(eye+10-y)/5.0));
    w=Math.Max(w,upper);
   }
   w=Math.Max(w,Ellipse(x,y,110,mouth,32,16));
   double dxn=Math.Max(0,Math.Max(96-x,x-125));
   double dyn=Math.Max(0,Math.Max(eye+12-y,y-(mouth-15)));
   w*=Math.Min(1,Math.Sqrt(dxn*dxn+dyn*dyn)/5.0);
   w*=Math.Max(0,Math.Min(1,(y-(eye-29))/5.0));
   if(w<=0)continue;
   int dst=((y+top)*512+x+146)*4,src=((y+(y<eye+12?eyeShift:mouthShift))*220+x+ox)*4;
   for(int c=0;c<3;c++)result[dst+c]=(byte)Math.Round(original[dst+c]*(1-w)+generated[src+c]*w);
  }
  // Reuse original eyebrow shape/texture with a two-pixel lift for the flustered reaction.
  // This is source-pixel compositing, not redrawing or smoothing brows.
  for(int y=eye-34;y<=eye-8;y++)for(int x=57;x<=161;x++){
   double w=0;foreach(int cx in new int[]{84,134})w=Math.Max(w,Ellipse(x,y,cx,eye-20,27,14));
   w*=Math.Max(0,Math.Min(1,(y-(eye-29))/5.0));
   if(w<=0)continue;
   int dst=((y+top)*512+x+146)*4,src=((y+top+2)*512+x+146)*4;
   for(int c=0;c<3;c++)result[dst+c]=(byte)Math.Round(result[dst+c]*(1-w)+original[src+c]*w);
  }
  return result;
 }



 public static int[] Check(byte[] a,byte[] b,int top,int eye,int mouth) {
  int changed=0,outside=0,nose=0,alpha=0;
  for(int y=0;y<1280;y++)for(int x=0;x<512;x++){
   int i=(y*512+x)*4;
   if(a[i+3]!=b[i+3])alpha++;
   if(a[i]==b[i]&&a[i+1]==b[i+1]&&a[i+2]==b[i+2]&&a[i+3]==b[i+3])continue;
   changed++;
   if(x<203||x>307||y<top+eye-29||y>top+mouth+17)outside++;
   if(x>=242&&x<=271&&y>=top+eye+12&&y<=top+mouth-15)nose++;
  }
  return new int[]{changed,outside,nose,alpha};
 }
}
